import React, { useState } from 'react';
import { Box, TextField, Button, Typography } from '@mui/material';
import axios from "axios";
import { validateAlphabet } from '../Healper/Validation.ts';
const ContactMe = () => {
  const [responseMessage, setResponseMessage] = useState("");
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === "name") {
      if (name === "" || validateAlphabet(value)) {
        setFormData((prevState) => ({
          ...prevState,
          [name]: value,
        }));
      }
    } else {
      setFormData((prevState) => ({
        ...prevState,
        [name]: value
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post("http://localhost:3000/api/products", formData, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      setResponseMessage(response.data.message);

      alert("form submitted", response.data.message);

      setFormData({ name: "", email: "", phone: '', message: "" });

    } catch (error) {
      setResponseMessage("Error: Could not submit the form");
      console.error("API error:", error);
    }
  };

  return (
    <Box
      sx={{
        width: '100%',
        maxWidth: '600px',
        margin: 'auto',
        padding: '16px',
      }}
    >
      <Typography variant="h4" gutterBottom className='heading'>
        Contact Me
      </Typography>

      <form onSubmit={handleSubmit}>
        <TextField
          className='heading'
          fullWidth
          size='small'
          label="Your Name"
          name="name"
          value={formData.name}
          onChange={handleChange}
          sx={{ marginBottom: '16px' }}
        />
        <TextField
          className='heading'
          fullWidth
          label="Your Email"
          size='small'
          name="email"
          value={formData.email}
          onChange={handleChange}
          type="email"
          sx={{ marginBottom: '16px' }}
        />
        <TextField
          className='heading'
          fullWidth
          label="Your Phone Number"
          name="phone"
          size='small'
          value={formData.phone}
          onChange={handleChange}
          type="tel"
          sx={{ marginBottom: '16px' }}
        />
        <TextField
          className='heading'
          fullWidth
          label="Your Message"
          size='small'
          name="message"
          value={formData.message}
          onChange={handleChange}
          multiline
          rows={4}
          sx={{ marginBottom: '16px' }}
        />

        <Button type="submit" size='small' variant="contained" color="primary" fullWidth>
          Submit
        </Button>
      </form>
    </Box>
  );
};

export default ContactMe;
